(7722282, 1271286, 114285, '<td valign="top">Stunning silkiness. My pick for blue.</td>', 'Stunning silkiness. My pick for blue.', '2022-06-27 22:57:50.000000', NULL, 1),
(7722283, 1271306, 114285, '<td valign="top">What you didnt have one without water drops on the lens ;)</td>', 'What you didnt have one without water drops on the lens ;)', '2022-06-27 22:58:43.000000', NULL, 1),
(7722499, 1271309, 112828, '<td valign="top">Love it!</td>', 'Love it!', '2022-07-01 00:29:06.000000', NULL, 1),
(7722500, 1271284, 112828, '<td valign="top">Fantastic foresty abstract..</td>', 'Fantastic foresty abstract..', '2022-07-01 00:29:33.000000', NULL, 1),
(7722501, 1271299, 112828, '<td valign="top">A bit darker than I''d like in the mids/shadows - but great focus</td>', 'A bit darker than I''d like in the mids/shadows - but great focus', '2022-07-01 00:29:59.000000', NULL, 1),
(7722502, 1271311, 112828, '<td valign="top">VERY smooth for a full second!</td>', 'VERY smooth for a full second!', '2022-07-01 00:30:28.000000', NULL, 1),
(7722503, 1271325, 96751, '<td valign="top">This is so groovy!</td>', 'This is so groovy!', '2022-07-01 00:31:30.000000', NULL, 1),
(7722504, 1271309, 96751, '<td valign="top">Subtle, but engaging.</td>', 'Subtle, but engaging.', '2022-07-01 00:31:59.000000', NULL, 1),
(7722505, 1271314, 112828, '<td valign="top">Love the starburst on the street lights - I never remember to do this since I''m always shooting wide open, but it looks so nice!</td>', 'Love the starburst on the street lights - I never remember to do this since I''m always shooting wide open, but it looks so nice!', '2022-07-01 00:32:40.000000', NULL, 1),
(7722506, 1271161, 96751, '<td valign="top">Astral travel is real.</td>', 'Astral travel is real.', '2022-07-01 00:32:42.000000', NULL, 1),
(7722507, 1271324, 112828, '<td valign="top">ZOOOM~!</td>', 'ZOOOM~!', '2022-07-01 00:32:49.000000', NULL, 1),
(7722508, 1271284, 96751, '<td valign="top">Glorious pastel tones</td>', 'Glorious pastel tones', '2022-07-01 00:33:08.000000', NULL, 1),
(7722509, 1271303, 112828, '<td valign="top">Not a bad idea - but very off level, and the subject is partly out of frame.</td>', 'Not a bad idea - but very off level, and the subject is partly out of frame.', '2022-07-01 00:33:22.000000', NULL, 1),
(7722510, 1271290, 112828, '<td valign="top">I''m not finding a clear focal point - and the image feels a little soft - finer details could be sharper - but the clouds and sky have a nice feel to them.</td>', 'I''m not finding a clear focal point - and the image feels a little soft - finer details could be sharper - but the clouds and sky have a nice feel to them.', '2022-07-01 00:35:20.000000', NULL, 1),
(7722512, 1271310, 112828, '<td valign="top">Fun that you''re showing the vibration of the strings!<br/> <br/>I think the white balance is a bit towards the yellow side here, and the image is a little soft, especially on the frets, but it''s a fun idea, and not badly done either!</td>', 'Fun that you''re showing the vibration of the strings! I think the white balance is a bit towards the yellow side here, and the image is a little soft, especially on the frets, but it''s a fun idea, and not badly done either!', '2022-07-01 00:36:48.000000', NULL, 1),
(7722601, 1271284, 30049, '<td valign="top">My favorite type of abstract.  :-)  Well done!</td>', 'My favorite type of abstract.  :-)  Well done!', '2022-07-01 17:59:01.000000', NULL, 1),
