(7722667, 1271311, 149964, '<td valign="top">I love the colour on this. I wonder if cropping it off-centre (putting centre tree on a third) might have added even more interest?</td>', 'I love the colour on this. I wonder if cropping it off-centre (putting centre tree on a third) might have added even more interest?', '2022-07-03 13:37:32.000000', NULL, 1),
(7722671, 1271304, 35334, '<td valign="top">This is my top choice. You have made creative use of motion in the one second exposure.</td>', 'This is my top choice. You have made creative use of motion in the one second exposure.', '2022-07-03 16:44:27.000000', NULL, 1),
